materials.css:
@font-face {
  font-family: 'Noto Serif SC Web';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url('https://fonts.gstatic.com/s/notoserifsc/v26/taiTGmRtCRMoE254uxjW5PWQqPt6_11c.woff2') format('woff2');
}
@font-face {
  font-family: 'Noto Serif SC Web';
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url('https://fonts.gstatic.com/s/notoserifsc/v26/taiTGmRtCRMoE254uxjW5PWQqPt6_11c.woff2') format('woff2');
}
/* ══════════════════════════════════════════
   1. 全局基底与浅蓝变量
   ══════════════════════════════════════════ */
.mix-game {
  font-family: 'Noto Serif SC Web', 'Noto Serif SC', 'Source Han Serif SC', 'Songti SC', serif !important;
  color: #ffffff !important;
  --mix-c-sky-border: rgba(162, 206, 235, 0.65);
  --mix-c-sky-light: rgba(225, 240, 252, 0.95);
  --mix-c-sky-btn: #78aed3;
  --mix-c-sky-btn-active: #5f9bc4;
  --mix-c-text-deep: #25445d;
}
/* ══════════════════════════════════════════
   2. 顶部栏：保持原背景完全不改，文字纯白
   ══════════════════════════════════════════ */
.mix-game-header,
.mix-game-header *,
.mix-game-title {
  color: #ffffff !important;
  font-weight: 600 !important;
  letter-spacing: 2px !important;
  text-shadow: 0 1px 4px rgba(0, 0, 0, 0.7) !important;
}
.mix-game-header .mix-icon-btn {
  background: var(--mix-c-sky-light) !important;
  border: 1px solid var(--mix-c-sky-border) !important;
  color: var(--mix-c-text-deep) !important;
  border-radius: 8px !important;
  box-shadow: 0 2px 6px rgba(40, 80, 110, 0.12) !important;
}
/* ══════════════════════════════════════════
   3. 正文基础排版：纯白打底
   ══════════════════════════════════════════ */
.mix-prose,
.mix-para,
.mix-narration {
  color: #ffffff !important;
  font-size: 15.5px !important;
  line-height: 1.85 !important;
  letter-spacing: 0.8px !important;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.6) !important;
}
.mix-para {
  text-indent: 2em !important;
  margin-bottom: 0.8em !important;
}
/* ══════════════════════════════════════════
   4. 特殊语义类名：全量赋古典雅色
   ══════════════════════════════════════════ */
/* ① 对白 —— 赋色：清澈晴空浅蓝 */
.mix-dialogue,
.mix-prose .mix-dialogue,
.mix-dialogue * {
  color: #9fe0ff !important;
  font-weight: 500 !important;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.7) !important;
}
/* ② 心声 / 心理活动 —— 赋色：温婉浅粉藕荷色 */
.mix-thought,
.mix-prose .mix-thought,
.mix-thought *,
.mix-prose em,
.mix-prose i {
  color: #eec1ce !important;
  font-style: normal !important;
  letter-spacing: 1px !important;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.7) !important;
}
/* ③ 强调 / 加粗 —— 赋色：淡雅明浅金 + 虚线 */
.mix-accent,
.mix-prose .mix-accent,
.mix-accent *,
.mix-prose strong,
.mix-prose b {
  color: #fae1b0 !important;
  font-weight: 600 !important;
  border-bottom: 1px dashed rgba(250, 225, 176, 0.7) !important;
  padding-bottom: 1px !important;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.7) !important;
}
/* ④ 场景过场行 —— 赋色：浅湖蓝 + 上下细线 */
.mix-scene,
.mix-prose .mix-scene {
  text-align: center !important;
  color: #a8d5f2 !important;
  font-size: 13.5px !important;
  letter-spacing: 3px !important;
  margin: 18px 0 !important;
  padding: 6px 0 !important;
  border-top: 1px solid rgba(162, 206, 235, 0.4) !important;
  border-bottom: 1px solid rgba(162, 206, 235, 0.4) !important;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.6) !important;
}
/* ══════════════════════════════════════════
   5. 气泡与对局卡片
   ══════════════════════════════════════════ */
.mix-user-turn {
  margin-bottom: 18px !important;
}
.mix-user-bubble {
  background: linear-gradient(135deg, rgba(88, 142, 179, 0.9) 0%, rgba(56, 105, 138, 0.9) 100%) !important;
  border: 1px solid rgba(162, 206, 235, 0.6) !important;
  border-radius: 12px 2px 12px 12px !important;
  color: #ffffff !important;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.2) !important;
  line-height: 1.8 !important;
}
.mix-assistant-turn {
  margin-bottom: 22px !important;
}
.mix-ticket-wrap,
.mix-encore-inline {
  border-radius: 8px !important;
  margin: 10px 0 16px !important;
}
.mix-turn-act {
  background: var(--mix-c-sky-light) !important;
  border: 1px solid var(--mix-c-sky-border) !important;
  color: #487c9f !important;
  border-radius: 6px !important;
}
/* ══════════════════════════════════════════
   6. 底部输入栏：浅蓝通透质感 + 40px严格等高对齐
   ══════════════════════════════════════════ */
.mix-game-inputbar {
  background: rgba(220, 238, 248, 0.88) !important;
  border-top: 1px solid var(--mix-c-sky-border) !important;
  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;
  padding: 8px 12px !important;
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  box-sizing: border-box !important;
}
/* ① 输入框：统一 40px 高度 */
.mix-game-input,
.mix-game-inputbar textarea,
.mix-game-inputbar input {
  flex: 1 !important;
  height: 40px !important;
  min-height: 40px !important;
  max-height: 40px !important;
  box-sizing: border-box !important;
  background: rgba(255, 255, 255, 0.95) !important;
  border: 1px solid var(--mix-c-sky-border) !important;
  border-radius: 8px !important;
  color: #1a3a52 !important;
  font-family: inherit !important;
  font-size: 14.5px !important;
  line-height: 22px !important;
  padding: 8px 12px !important;
}
.mix-game-input:focus {
  border-color: #6faad4 !important;
  background: #ffffff !important;
}
/* ② 左侧辅助按钮：40px × 40px 正方形等高 */
.mix-game-inputbar .mix-icon-btn {
  width: 40px !important;
  height: 40px !important;
  min-width: 40px !important;
  min-height: 40px !important;
  max-height: 40px !important;
  box-sizing: border-box !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  background: rgba(255, 255, 255, 0.95) !important;
  border: 1px solid var(--mix-c-sky-border) !important;
  color: #3b6b8c !important;
  border-radius: 8px !important;
  box-shadow: 0 2px 6px rgba(40, 80, 110, 0.08) !important;
}
/* ③ 发送按钮：清透浅蓝渐变，高度 40px 等高，原生图标自然居中 */
.mix-send-btn {
  height: 40px !important;
  min-height: 40px !important;
  max-height: 40px !important;
  box-sizing: border-box !important;
  padding: 0 16px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  background: linear-gradient(135deg, #8bc2e8 0%, #5e9ec9 100%) !important;
  border: 1px solid rgba(110, 170, 210, 0.8) !important;
  color: #ffffff !important;
  border-radius: 8px !important;
  box-shadow: 0 2px 8px rgba(60, 120, 160, 0.25) !important;
  cursor: pointer !important;
}
/* 保障发送按钮里的原生 SVG 图标比例饱满、不缩小变形 */
.mix-send-btn svg {
  width: 18px !important;
  height: 18px !important;
  display: block !important;
  fill: currentColor !important;
}
.mix-send-btn:active {
  background: linear-gradient(135deg, #74b0d9 0%, #4f8db8 100%) !important;
}
